    public function getledgercreditdebit()
{
    $admin_id = $this->session->userdata['id'];
    $month_start = date('Y-m-01');
    $month_end = date('Y-m-t');

    // Subquery to get latest transaction date per ledger
    $sub_latest_tx = "
        SELECT 
            MAX(created_at) 
        FROM coin_transactions 
        WHERE 
            (receiver_id = l.id OR sender_id = l.id)
            AND created_at BETWEEN '{$month_start}' AND '{$month_end}'
    ";

    // Subquery to get latest transaction's amount per ledger
    // (Optional) You can also do more complex subqueries if needed

    $this->db->select("
        l.id as ledger_id,
        l.ledger_name AS account_name,
        ({$sub_latest_tx}) AS transaction_date,
        
        (SELECT SUM(ct.amount) 
         FROM coin_transactions ct 
         WHERE ct.receiver_id = l.id 
         AND ct.created_at BETWEEN '{$month_start}' AND '{$month_end}'
        ) AS credit,

        (SELECT SUM(ct.amount) 
         FROM coin_transactions ct 
         WHERE ct.sender_id = l.id 
         AND ct.created_at BETWEEN '{$month_start}' AND '{$month_end}'
        ) AS withdraw
    ", false);

    $this->db->from('tbl_ledger l');
    $this->db->where('l.updated_by', $admin_id);
    $this->db->order_by('transaction_date', 'DESC'); // Latest ledgers first

    $query = $this->db->get();

    return json_encode($query->result_array());
}


