    function get_tbl_ledger_byupdatedbyformasters($id)

    {

        //return $this->db->get_where('tbl_ledger',array('status'=>1,'updated_by'=>$id))->result();

        $this->db->select('tbl_ledger.*, tbl_agent.agent_name');
        $this->db->from('tbl_ledger');
        $this->db->join('tbl_agent', 'tbl_ledger.agent_id = tbl_agent.id', 'left');
        $this->db->where('tbl_ledger.status', 1);
        $this->db->where('tbl_ledger.updated_by', $id);

        return $this->db->get()->result();
    }

